int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns)) {
        return -EINVAL;
    }

    if (!sctp_assoc_lookup(sk, id)) {
        return -ENOENT;
    }

    if (waitqueue_active(&sk->sk_wait)) {
        return -EBUSY;
    }

    if (sk->sk_type != SOCK_SEQPACKET && sk->sk_type != SOCK_STREAM) {
        return -EINVAL;
    }

    struct socket *newsock;
    if (sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type, sk->sk_protocol, &newsock)) {
        return -ENOMEM;
    }

    struct sock *newsk = newsock->sk;
    newsk->sk_type = sk->sk_type;
    newsk->sk_family = sk->sk_family;
    newsk->sk_protocol = sk->sk_protocol;

    if (sctp_assoc_migrate(sk, id, newsk)) {
        sock_release(newsock);
        return -EFAULT;
    }

    *sockp = newsock;
    return 0;
}

int sctp_assoc_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (!sctp_assoc_lookup(sk, id))
        return -ENOENT;

    if (sk->sk_shutdown & RCV_SHUTDOWN)
        return -EINVAL;

    if (sk->sk_type != SOCK_STREAM)
        return -EINVAL;

    ret = sock_create_kern(sock_net(sk), sk->sk_family, sk->sk_type,
                           sk->sk_protocol, sockp);
    if (ret)
        return ret;

    sctp_assoc_migrate(sk, id, (*sockp)->sk);
    sctp_copy_sock_options(sk, (*sockp)->sk);
    sctp_copy_sock_state(sk, (*sockp)->sk);
    sctp_copy_sock_info(sk, (*sockp)->sk);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;
    struct socket *new_sock = NULL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -EINVAL;

    if (!sctp_assoc_exists(sk, id))
        return -ENOENT;

    if (sctp_has_waiters(sk, id))
        return -EBUSY;

    if (sctp_sock_style(sk) != SOCK_STREAM)
        return -EOPNOTSUPP;

    ret = sock_create(sock_net(sk), PF_INET, SOCK_STREAM, 0, &new_sock);
    if (ret < 0)
        goto out;

    ret = sctp_copy_props(sk, new_sock->sk);
    if (ret < 0)
        goto out;

    ret = sctp_migrate_assoc(sk, id, new_sock->sk);
    if (ret < 0)
        goto out;

    *sockp = new_sock;
    return 0;

out:
    if (new_sock)
        sock_release(new_sock);
    return ret;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;
    struct socket *new_sock = NULL;
    struct sock *new_sk = NULL;

    if (!net_eq(sock_net(sk), current->nsproxy->net_ns))
        return -ENOTCONN;

    if (!sctp_assoc_valid(sk, id))
        return -EINVAL;

    if (sctp_has_pending_threads(sk, id))
        return -EBUSY;

    if (sctp_style(sk, UDP)) {
        ret = sock_create_kern(sock_net(sk), PF_INET, SOCK_STREAM, IPPROTO_SCTP, &new_sock);
        if (ret < 0)
            return ret;

        new_sk = new_sock->sk;
        sctp_inherit_properties(sk, new_sk, id);
        sctp_migrate_association(sk, new_sk, id);

        *sockp = new_sock;
        ret = 0;
    }

    return ret;
}
